const normalizeSkill = (value = '') => value.trim().toLowerCase();

const uniqueByNormalized = (items = []) => {
  const seen = new Set();
  return items.filter((item) => {
    const key = normalizeSkill(item);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

const scoreSkillMatch = (skill, query) => {
  const normalizedSkill = normalizeSkill(skill);
  const normalizedQuery = normalizeSkill(query);

  if (!normalizedQuery) return 0;
  if (normalizedSkill === normalizedQuery) return 1000;
  if (normalizedSkill.startsWith(normalizedQuery)) return 900;

  const words = normalizedSkill.split(/[\s/\-_.]+/).filter(Boolean);
  if (words.some((word) => word === normalizedQuery)) return 850;
  if (words.some((word) => word.startsWith(normalizedQuery))) return 800;

  const compactSkill = normalizedSkill.replace(/[\s/\-_.]+/g, '');
  const compactQuery = normalizedQuery.replace(/[\s/\-_.]+/g, '');
  if (compactSkill.startsWith(compactQuery)) return 760;
  if (normalizedSkill.includes(normalizedQuery)) return 700;
  if (compactSkill.includes(compactQuery)) return 650;

  const queryTokens = normalizedQuery.split(/[\s/\-_.]+/).filter(Boolean);
  if (queryTokens.length > 1 && queryTokens.every((token) => normalizedSkill.includes(token))) {
    return 600;
  }

  return -1;
};

export const getSkillSuggestions = (query = '', selectedSkills = [], limit = 12) => {
  const normalizedQuery = normalizeSkill(query);
  const selectedSet = new Set(selectedSkills.map(normalizeSkill));

  const availableSkills = skillLibrary.filter(
    (skill) => !selectedSet.has(normalizeSkill(skill))
  );

  if (!normalizedQuery) {
    return availableSkills.slice(0, limit);
  }

  return availableSkills
    .map((skill) => ({ skill, score: scoreSkillMatch(skill, normalizedQuery) }))
    .filter(({ score }) => score >= 0)
    .sort((a, b) => {
      const scoreDiff = b.score - a.score;
      if (scoreDiff) return scoreDiff;
      const lengthDiff = a.skill.length - b.skill.length;
      return lengthDiff || a.skill.localeCompare(b.skill);
    })
    .slice(0, limit)
    .map(({ skill }) => skill);
};

export const hasSkill = (skill) => {
  const normalizedSkill = normalizeSkill(skill);
  return skillLibrary.some((item) => normalizeSkill(item) === normalizedSkill);
};

export const getSkillCount = () => skillLibrary.length;

export const getSkillsByKeyword = (keyword, limit = 100) => {
  const normalizedKeyword = normalizeSkill(keyword);
  if (!normalizedKeyword) return [];
  return skillLibrary
    .filter((skill) => normalizeSkill(skill).includes(normalizedKeyword))
    .slice(0, limit);
};

export const getAllSkills = () => [...skillLibrary];

export const mergeSelectedSkills = (existingSkills = [], newSkills = []) => {
  return uniqueByNormalized([...existingSkills, ...newSkills]);
};
